bootforge/engineering-practice/practice/.starter:
export function applyPatch(task, patch) {
  return { ...task, ...patch, done: patch.done || task.done };
}

bootforge/engineering-practice/practice/.solution:
export function applyPatch(task, patch) {
  const next = { ...task };
  if (Object.hasOwn(patch, 'title')) {
    if (typeof patch.title !== 'string' || !patch.title.trim()) throw new Error('invalid title');
    next.title = patch.title.trim();
  }
  if (Object.hasOwn(patch, 'done')) {
    if (typeof patch.done !== 'boolean') throw new Error('invalid done');
    next.done = patch.done;
  }
  return next;
}

