export function updateInventory(item, patch) {
  const next = { ...item };
  if (Object.hasOwn(patch, 'label')) {
    if (typeof patch.label !== 'string' || !patch.label.trim()) throw new Error('invalid label');
    next.label = patch.label.trim();
  }
  if (Object.hasOwn(patch, 'stock')) {
    if (!Number.isSafeInteger(patch.stock) || patch.stock < 0) throw new Error('invalid stock');
    next.stock = patch.stock;
  }
  return next;
}

