import assert from 'node:assert/strict';
export function verify(candidate) {
  const rows = ['d','a','c','b','e'];
  const before = [...rows];
  const first = candidate(rows, 1, 2);
  assert.deepStrictEqual(first, ['d','a']);
  assert.notStrictEqual(first, rows);
  assert.deepStrictEqual(rows, before);
  assert.deepStrictEqual(candidate(rows, 2, 2), ['c','b']);
  assert.deepStrictEqual(candidate(rows, 3, 2), ['e']);
  assert.deepStrictEqual(candidate(rows, 4, 2), []);
  assert.deepStrictEqual(candidate([], 1, 2), []);
  assert.deepStrictEqual(candidate(rows, 1, 10), before);
  assert.deepStrictEqual(rows, before);
}

