import assert from 'node:assert/strict';
export function verify(candidate) {
  const rows = [
    {id:3,orgId:'a',deletedAt:null},
    {id:2,orgId:'b',deletedAt:null},
    {id:4,orgId:'a',deletedAt:0},
    {id:1,orgId:'a'},
    {id:5,orgId:'a',deletedAt:100},
  ];
  const before = structuredClone(rows);
  assert.deepStrictEqual(candidate(rows,'a'), [before[0],before[3]]);
  assert.deepStrictEqual(rows,before);
  assert.deepStrictEqual(candidate(rows,'b'), [before[1]]);
  assert.deepStrictEqual(candidate(rows,'missing'), []);
  assert.deepStrictEqual(candidate([],'a'), []);
  assert.deepStrictEqual(rows,before);
}

